    where {parseJSON val = GHC.Base.pure (if | val GHC.Classes.== "custom" -> AccountTypeEnumCustom
                                             | val GHC.Classes.== "express" -> AccountTypeEnumExpress
                                             | val GHC.Classes.== "none" -> AccountTypeEnumNone
